import{_ as i,l as r,o as a,c,v as t,p as s,x as o,d,i as p,S as l}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"内容协商与压缩","description":"","frontmatter":{"title":"内容协商与压缩","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/content-negotiation.md","filePath":"cs/content-negotiation.md","lastUpdated":1789023840000}'),h={name:"cs/content-negotiation.md"};function E(_,e,C,g,A,u){const n=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="内容协商与压缩" tabindex="-1">内容协商与压缩 <a class="header-anchor" href="#内容协商与压缩" aria-label="Permalink to &quot;内容协商与压缩&quot;">​</a></h1><div class="epigraph"><p>Accept 头让客户端声明能懂的媒体类型、语言与编码；服务器挑表示，Content-Encoding 可 gzip，缓存必须 Vary。</p><footer>—— 据 RFC 9110 内容协商；RFC 9112 传输编码对照；RFC 1952 gzip 整理</footer></div><p><a href="/cs/cookies-sessions">上一课</a> 的头已影响缓存。主干<a href="/cs/http-semantics">缓存头</a> 未展开协商。缺口是 <strong>Accept* 与压缩</strong>：表示选择、<code>Vary</code>、与 chunked 的分工。本课不把 WebSocket 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一 URI 可有 JSON/HTML、中英、gzip/br。协商：客户端权重，服务器选或 406。压缩减带宽，CPU 换 \\(C\\) 上的头税；已加密的图片再 gzip 无益。<code>Content-Encoding</code> 是表示的一部分，<code>Transfer-Encoding</code> 是跳上的（1.1 chunked），H2/H3 不用 TE。中间缓存若忽略 <code>Vary: Accept-Encoding</code> 会把 gzip 给不能解的客户。</p><p>不要把压缩写成线路码 8B/10B。</p><p><span class="marginnote">RFC 9110 第 12 章。Brotli/zstd 是编码登记问题。本课不调压缩级别。</span></p><h3 id="压缩要-vary" tabindex="-1">压缩要 Vary <a class="header-anchor" href="#压缩要-vary" aria-label="Permalink to &quot;压缩要 Vary&quot;">​</a></h3><p>Accept 选表示；Content-Encoding 属表示，不是 1.1 的 TE。已压缩媒体再 gzip 无益。加密信道上压缩有历史风险。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：Accept → 选表示 → 可选压缩 → Vary。对照：传输层 TSO 不看媒体类型。与 PMTUD 无关直接，但压缩后长度变，影响是否分块。</p>',11)),(a(),s(l,null,{default:o(()=>[p(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22Accept%20%E6%97%8F%22%5D%20--%3E%20NEG%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%80%89%E6%8B%A9%22%5D%0A%20%20NEG%20--%3E%20CE%5B%22Content-Encoding%22%5D%0A%20%20CE%20--%3E%20VARY%5B%22%E7%BC%93%E5%AD%98%E6%8C%89%20Vary%20%E9%94%AE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CDN 要按 Vary 键存多份，否则省的带宽变成错页。QUIC 0-RTT 的协商头也可重放。语言协商与 GeoDNS 后课可叠加。安全：压缩与加密同用有 CRIME 一类历史，TLS 上谨慎压缩。</p><p>chunked 与 gzip 常叠：先压缩再分块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入内容编码登记的全部 IANA 表。WebSocket 是下一课。后课默认：协商选表示；压缩要 Vary。</p><p>强制只 gzip 而不看 Accept-Encoding 会破坏老客户。</p><p>上一课留下的缺口在本课收口；「内容协商与压缩」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/websocket">WebSocket</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Accept 驱动表示选择。</li><li>Content-Encoding 属表示；要 Vary。</li><li>与 1.1 传输编码不是一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9110；gzip RFC 1952。</li></ul>',10))])}const T=i(h,[["render",E]]);export{f as __pageData,T as default};
